"""Tests of the roadmap harness (tools/harness/aim.py) on a throwaway plan."""
from __future__ import annotations

import importlib.util
import io
import json
import os
import shutil
import subprocess
import sys
import tempfile
import unittest
from contextlib import redirect_stdout
from pathlib import Path
from unittest import mock

REPO = Path(__file__).resolve().parent.parent
SCRIPT = REPO / "tools" / "harness" / "aim.py"

ROADMAP = """# Roadmap

## Steps

<!-- aim:steps start: generated by ./aim, do not edit -->
<!-- aim:steps end -->

## Decisions

<!-- aim:decisions start: generated by ./aim, do not edit -->
<!-- aim:decisions end -->

## Working protocol for every chat

1. Verify first.

## Step sections

### S01 — First step

**Goal.** Something.

**Acceptance.**

- [ ] It works.

### S02 — Second step

**Goal.** Something else.
"""

STEPS = {
    "version": 1,
    "milestones": {"M1": {"title": "First", "steps": ["S01", "S02", "C1"], "checks": []}},
    "steps": [
        {"id": "S01", "phase": "0", "milestone": "M1", "title": "First step", "depends_on": [], "decisions": [],
         "issues": [], "prs": [], "chats": [4], "status": "todo"},
        {"id": "S02", "phase": "0", "milestone": "M1", "title": "Second step", "depends_on": ["S01"],
         "decisions": ["D2"], "issues": [], "prs": [], "chats": [], "status": "todo"},
    ],
    "checks": [{"id": "C1", "title": "Owner looks", "depends_on": ["S01"], "steps_to_do": ["Look."],
                "status": "todo"}],
}

DECISIONS = {"version": 1, "decisions": [
    {"id": "D1", "status": "accepted", "decision": "Use the store.", "date": "1 Nov 2026"},
    {"id": "D2", "status": "open", "question": "Which backend?", "blocks": "S02"},
]}


class HarnessTest(unittest.TestCase):
    def setUp(self):
        self.tmp = Path(tempfile.mkdtemp())
        plans = self.tmp / "docs" / "plans"
        (plans / "handoffs").mkdir(parents=True)
        (plans / "handoffs" / "chat-03.md").write_text("# Chat 03 handoff — earlier\n\n## Next step\n\nS01\n")
        (self.tmp / "AGENTS.md").write_text("# Agents\n")
        (plans / "steps.json").write_text(json.dumps(STEPS))
        (plans / "decisions.json").write_text(json.dumps(DECISIONS))
        (plans / "prototype-roadmap.md").write_text(ROADMAP)
        shutil.copy(REPO / "docs" / "plans" / "harness-guide.md", plans / "harness-guide.md")
        (self.tmp / "tools" / "harness").mkdir(parents=True)
        shutil.copy(REPO / "tools" / "harness" / "config.json", self.tmp / "tools" / "harness" / "config.json")
        with mock.patch.dict(os.environ, {"AIM_ROOT": str(self.tmp)}):
            spec = importlib.util.spec_from_file_location("aim_under_test", SCRIPT)
            self.aim = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(self.aim)
        self.aim.render()

    def tearDown(self):
        shutil.rmtree(self.tmp)

    def run_aim(self, *argv: str) -> str:
        out = io.StringIO()
        with redirect_stdout(out), mock.patch.object(sys.stdin, "isatty", return_value=False):
            self.aim.main(list(argv))
        return out.getvalue()

    def step(self, sid: str) -> dict:
        data = json.loads((self.tmp / "docs" / "plans" / "steps.json").read_text())
        return next(t for t in data["steps"] + data["checks"] if t["id"] == sid)

    def test_render_fills_the_roadmap_blocks_and_status(self):
        roadmap = (self.tmp / "docs" / "plans" / "prototype-roadmap.md").read_text()
        self.assertIn("| S02 | 0 | Second step | S01, D2 | todo |", roadmap)
        self.assertIn("| D2 | open | Which backend? | S02 |", roadmap)
        self.assertIn("### S01 — First step", roadmap)
        status = (self.tmp / "docs" / "plans" / "STATUS.md").read_text()
        self.assertIn("- **S01** First step", status)
        self.assertIn("Use the store.", (self.tmp / "docs" / "plans" / "DECISIONS.md").read_text())
        self.assertIn("up to date", self.run_aim("render", "--check"))

    def test_claim_takes_the_next_chat_number_after_files_and_recorded_chats(self):
        self.run_aim("claim", "S01", "--agent", "codex")
        s01 = self.step("S01")
        self.assertEqual(s01["status"], "in_progress")
        self.assertEqual(s01["owner"], "codex")
        self.assertEqual(s01["current_chat"], 5)  # chat-03.md exists, chat 4 is recorded
        self.assertEqual(s01["chats"], [4, 5])

    def test_claim_refuses_a_step_that_waits_and_an_owner_check(self):
        with self.assertRaises(SystemExit) as e:
            self.run_aim("claim", "S02", "--agent", "codex")
        self.assertIn("S01, D2", str(e.exception))
        with self.assertRaises(SystemExit) as e:
            self.run_aim("claim", "C1", "--agent", "codex")
        self.assertIn("owner check", str(e.exception))

    def test_handoff_then_review_needs_a_complete_handoff(self):
        self.run_aim("claim", "S01", "--agent", "claude")
        self.run_aim("handoff", "S01", "--agent", "claude", "--done", "Built it.", "--next", "S02")
        path = self.tmp / "docs" / "plans" / "handoffs" / "chat-05.md"
        text = path.read_text()
        self.assertIn("# Chat 05 handoff — S01 First step", text)
        self.assertIn("Built it.", text)
        with self.assertRaises(SystemExit) as e:
            self.run_aim("review", "S01", "--pr", "12")
        self.assertIn("TODO(aim)", str(e.exception))
        path.write_text(text.replace("TODO(aim)", "Checked"))
        self.run_aim("handoff", "S01", "--agent", "codex", "--done", "More.", "--next", "Publish.")
        self.assertIn("## Update", path.read_text())
        self.run_aim("review", "S01", "--pr", "12")
        self.assertEqual(self.step("S01")["status"], "review")
        self.assertEqual(self.step("S01")["prs"], [12])
        self.run_aim("done", "S01")
        self.assertEqual(self.step("S01")["status"], "done")

    def test_owner_actions_refuse_without_the_owner(self):
        self.run_aim("propose", "D2", "Keep SQLite.", "--why", "simplest", "--agent", "codex")
        with self.assertRaises(SystemExit) as e:
            self.run_aim("accept", "D2")
        self.assertIn("owner", str(e.exception))
        with self.assertRaises(SystemExit):
            self.run_aim("done", "C1")

    def test_propose_accept_makes_the_step_ready(self):
        out = self.run_aim("propose", "New question answer.", "--question", "New?", "--why", "needed",
                           "--blocks", "S02", "--agent", "codex")
        self.assertIn("D3 proposed", out)
        self.run_aim("propose", "D2", "Keep SQLite.", "--why", "simplest")
        decisions = (self.tmp / "docs" / "plans" / "DECISIONS.md").read_text()
        self.assertIn("## Waiting for the owner", decisions)
        self.run_aim("claim", "S01", "--agent", "claude")
        self.run_aim("done", "S01", "--force")
        out = self.run_aim("accept", "D2", "--yes")
        self.assertIn("Ready now: S02", out)
        self.run_aim("reject", "D3", "--why", "not now", "--yes")
        data = json.loads((self.tmp / "docs" / "plans" / "decisions.json").read_text())
        d3 = next(d for d in data["decisions"] if d["id"] == "D3")
        self.assertEqual(d3["status"], "open")
        self.assertNotIn("proposal", d3)

    def test_prompt_contains_the_step_protocol_and_decisions(self):
        out = self.run_aim("prompt", "S02", "--tool", "chatgpt")
        self.assertIn("### S02 — Second step", out)
        self.assertIn("1. Verify first.", out)
        self.assertNotIn("### S01", out)
        self.assertIn("D2 (open): Which backend?", out)
        self.assertIn('<file path="AGENTS.md">', out)
        self.assertTrue((self.tmp / "var" / "prompts" / "S02-chatgpt.md").exists())

    def test_check_asks_for_node_modules_instead_of_running_npm(self):
        (self.tmp / "apps").mkdir()
        (self.tmp / "apps" / "package.json").write_text("{}")
        out = io.StringIO()
        with redirect_stdout(out):
            ok = self.aim.run_checks([{"name": "npm test", "cmd": "exit 0", "cwd": "apps"}], {"env": {}})
        self.assertFalse(ok)
        self.assertIn("npm ci --ignore-scripts", out.getvalue())
        (self.tmp / "apps" / "node_modules").mkdir()
        with redirect_stdout(io.StringIO()):
            self.assertTrue(self.aim.run_checks([{"name": "npm test", "cmd": "exit 0", "cwd": "apps"}], {"env": {}}))

    def test_selfcheck_reports_unknown_ids(self):
        data = json.loads((self.tmp / "docs" / "plans" / "steps.json").read_text())
        data["steps"][1]["depends_on"].append("S99")
        problems = self.aim.validate(data, json.loads((self.tmp / "docs" / "plans" / "decisions.json").read_text()))
        self.assertIn("S02: depends on unknown S99", problems)


class RepositoryPlanTest(unittest.TestCase):
    def test_the_repository_plan_passes_selfcheck(self):
        r = subprocess.run([sys.executable, str(SCRIPT), "selfcheck"], capture_output=True, text=True,
                           env={k: v for k, v in os.environ.items() if k != "AIM_ROOT"})
        self.assertEqual(r.returncode, 0, r.stdout + r.stderr)


if __name__ == "__main__":
    unittest.main()
